      def generated_rule_sections
        [
          rule_section(:aim, GameRoomRules.translate("The aim"),
            GameRoomRules.translate("Darts is an audio aiming game for one to eight players. Guide the moving sound towards the centre of the target and score as many points as possible. Each round gives every player three darts.")),
          rule_section(:turn, GameRoomRules.translate("A throw"),
            GameRoomRules.translate("Press Space to begin aiming a dart. The cursor starts at a random position away from the centre and immediately begins to drift. For the first second you can correct it, but you cannot throw. A short ready cue tells you when the throw is unlocked."),
            GameRoomRules.translate("Use the arrow keys to correct the cursor, then press Space again to throw. The release sound is followed by the dart striking the target and a separate cue whose pitch represents the points scored. The next dart waits for another press of Space, so its aiming sound does not begin while the previous result is still being announced.")),
          rule_section(:aiming, GameRoomRules.translate("Finding the centre by sound"),
            GameRoomRules.translate("The aiming sound moves left and right in stereo. Its pitch and volume describe distance from the centre: it becomes higher and stronger as you get closer, and lower and softer as you move away. This relationship is the same in every direction."),
            GameRoomRules.translate("Every arrow press moves the cursor by a slightly different distance. After a correction it stays steadier for a short time, then continues to drift, usually outwards. The drift becomes faster near the valuable centre, so listening and timing matter more than repeating a fixed sequence of keys."),
            GameRoomRules.translate("A wooden cue marks the edge of the circular target. You can still move in the square playfield outside it, but a dart thrown there scores nothing. A different metallic cue means that the cursor has reached the outer limit and cannot move farther in that direction.")),
          rule_section(:time, GameRoomRules.translate("Time for a dart"),
            GameRoomRules.translate("With a time limit, three low cues count down the final three seconds. If time runs out, the table setting either throws from the cursor's current position or awards zero points. The clock starts only after the ready cue, not when you first press Space."),
            GameRoomRules.translate("You can also choose no time limit. In that case the cursor keeps drifting until you throw.")),
          rule_section(:scoring, GameRoomRules.translate("Scoring and the winner"),
            GameRoomRules.translate("A hit scores from 1 to 100 points according to its distance from the centre. The exact centre is worth 100 points; the value falls continuously towards the edge. A dart outside the circular target scores zero."),
            GameRoomRules.translate("After the selected number of rounds, the player with the highest total wins. If several leaders are tied, each of them throws one additional dart. Further one-dart tie-breaks continue only among players who remain tied until one player has the best result. In a solo game, the final total is your result.")),
          rule_section(:options, GameRoomRules.translate("Difficulty and match options"),
            GameRoomRules.translate("Easy, normal and hard difficulty change the cursor's correction accuracy, how long it remains steady after a correction and how quickly it drifts. Progressive difficulty begins easy, changes to normal and finishes hard as the selected rounds pass."),
            GameRoomRules.translate("A match can last 1, 3, 5 or 10 rounds. You can separately choose the time for one dart and what happens when it expires.")),
          rule_section(:training, GameRoomRules.translate("Sound training"),
            GameRoomRules.translate("Sound training is available at a one-player table. It uses the same aiming and scoring, but speech also announces the sector when you enter a different one, the start and final seconds of the clock, both boundaries, manual or automatic throws, hits and misses. Press C to repeat the current sector."),
            GameRoomRules.translate("Training does not turn off your screen reader. Ordinary game mode leaves the cursor itself sound-only, while normal interface labels, scores and results remain spoken.")),
          rule_section(:controls, GameRoomRules.translate("Keyboard and mouse controls"),
            GameRoomRules.translate("Space: start aiming or throw after the ready cue."),
            GameRoomRules.translate("Arrows: correct the audio cursor."),
            GameRoomRules.translate("S: read the scores."),
            GameRoomRules.translate("C: repeat the current sector in Sound training."),
            GameRoomRules.translate("Ctrl+P: open personal Darts settings and choose one of the three aiming sounds."),
            GameRoomRules.translate("Optional mouse control: relative movement corrects the cursor and the left button starts aiming or throws. Enable it in the table settings before play."))
        ]
      end

